"""Self-contained offline triage dashboard. All evidence is rendered as text."""
HTML=r'''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; base-uri 'none'; form-action 'none'"><title>Passive Scan v8.2 · 증거와 진단 커버리지</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d1422;color:#e6edf8;font:14px/1.6 system-ui,sans-serif}header,main{padding:24px 4vw}header{border-bottom:1px solid #2c3b55}h1{margin:0;font-size:27px}h2{font-size:19px;margin-top:0}.muted{color:#a7b7d0}.note{color:#ffd28c}.stats,.toolbar,nav,.buttons{display:flex;gap:10px;flex-wrap:wrap}.stat,article{background:#17243a;border:1px solid #2f415f;border-radius:12px;padding:15px}.stat b{display:block;font-size:25px;color:#91ceff}.stats{margin:16px 0}nav{margin-top:18px}input,select,button,textarea{font:inherit;background:#1b2c46;color:inherit;border:1px solid #425a7e;border-radius:8px;padding:8px}button{cursor:pointer}button.active{background:#295b89}input{min-width:230px}.toolbar{margin-bottom:15px}.layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:18px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;border-bottom:1px solid #31445e;text-align:left;vertical-align:top}th{background:#20334f;position:sticky;top:0}td{overflow-wrap:anywhere}tr[data-id]{cursor:pointer}tr.selected,tr[data-id]:hover{background:#244364}.tablewrap{max-height:65vh;overflow:auto;border:1px solid #31445e;border-radius:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0b1424;padding:12px;border-radius:8px;max-height:42vh;overflow:auto;font:12px/1.6 ui-monospace,monospace}article{min-width:0}textarea{width:100%;min-height:80px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.diff-left{border-left:3px solid #f7bc75}.diff-right{border-left:3px solid #83c6fa}.high{color:#ffbb89}.medium{color:#ffdf8c}.low{color:#97badb}.panel[hidden]{display:none}.pager{margin:10px 0}.message{color:#8ae0bf}#detailTitle{overflow-wrap:anywhere}@media(max-width:1000px){.layout,.pair{grid-template-columns:1fr}.tablewrap{max-height:45vh}} </style>
<header><h1>Passive Scan <span style="color:#91ceff">v8.2</span></h1><p class="muted">증거 기반 우선순위 · 계정 비교 · 기능 흐름 · 진단 커버리지</p><p class="note">검토 후보와 응답 차이는 취약점 확정이 아닙니다. 미검토·미수집을 정상으로 판정하지 않습니다. 이 보고서는 대상에 요청을 보내지 않습니다.</p><div class="stats" id="stats"></div><nav><button data-view="requests" class="active">요청 / 후보</button><button data-view="compare">계정 비교</button><button data-view="coverage">커버리지</button><button data-view="flows">기능 흐름</button><button data-view="changes">JS 변경분</button></nav></header>
<main><section id="requests" class="panel"><div class="toolbar"><input id="search" placeholder="URL · body 값 · 계정 · 기능 검색"><select id="actor"><option value="">모든 계정</option></select><select id="stateFilter"><option value="">모든 검토 상태</option></select><select id="priority"><option value="">모든 우선순위</option><option>high</option><option>medium</option><option>low</option></select><select id="method"><option value="">모든 메소드</option></select><select id="source"><option value="">모든 출처</option></select><select id="observed"><option value="">모든 관찰 상태</option><option value="true">실제 요청</option><option value="false">정적 발견</option></select></div><p id="visible" class="muted"></p><div class="layout"><div><div class="tablewrap"><table><thead><tr><th>우선순위</th><th>요청</th><th>계정 / 기능</th><th>검토 상태</th></tr></thead><tbody id="rows"></tbody></table></div><div class="buttons pager"><button id="prev">이전</button><span id="pageNo"></span><button id="next">다음</button></div></div><article><h2 id="detailTitle">요청을 선택하세요</h2><p id="metadata" class="muted"></p><h3>추천 이유 · 다음 확인 사항</h3><div id="hints"></div><p id="missing" class="note"></p><div class="buttons"><button data-tab="request" class="active">요청</button><button data-tab="response">응답</button><button data-tab="json">전체 기록</button></div><pre id="packet"></pre><h3>수집 상태</h3><pre id="bodyState"></pre><h3>검토자가 기록하는 상태</h3><select id="reviewState"></select><textarea id="reviewNote" placeholder="확인 / 오탐 결론에는 증거와 판단 근거를 입력하세요. 토큰은 입력하지 마세요."></textarea><div class="buttons"><button id="saveReview">이 화면에 적용</button><button id="exportReviews">검토 변경 내보내기</button></div><p id="reviewMessage" class="message"></p><p class="muted">내보낸 JSON을 request_inventory.py review --file로 가져온 뒤 보고서를 재생성하면 DB에 반영됩니다.</p></article></div></section>
<section id="compare" class="panel" hidden><h2>동일 자원·payload의 계정별 응답 비교</h2><p class="note">다른 자원 ID는 같은 요청으로 비교하지 않습니다. 응답 생략은 비교 불가로 표시하며, 차이 없는 응답도 정상의 증거로 단정하지 않습니다.</p><select id="pairSelect"></select><p id="pairMeta"></p><div class="pair"><article class="diff-left"><h3 id="leftTitle"></h3><pre id="leftPacket"></pre></article><article class="diff-right"><h3 id="rightTitle"></h3><pre id="rightPacket"></pre></article></div><h3>정규화된 차이</h3><div class="tablewrap"><table><thead><tr><th>필드</th><th>왼쪽</th><th>오른쪽</th></tr></thead><tbody id="diffRows"></tbody></table></div></section>
<section id="coverage" class="panel" hidden><h2>진단 커버리지</h2><p class="muted">경로 ID 묶기는 표시용입니다. 개별 URL·값·증거를 삭제하거나 병합하지 않습니다. 명세와 관찰의 필드 구조가 다르면 별도 항목으로 남습니다.</p><div class="tablewrap"><table><thead><tr><th>메소드 / 경로</th><th>발견 / 관찰</th><th>계정</th><th>검토 상태</th><th>부족한 정보</th></tr></thead><tbody id="coverageRows"></tbody></table></div></section>
<section id="flows" class="panel" hidden><h2>기능별 요청 흐름</h2><p class="note">scenario와 capture_id가 같은 계정·조직의 관찰만 연결합니다. 값 일치는 추정이며 서버 의존 관계의 확정 증거가 아닙니다.</p><div id="flowRows"></div></section>
<section id="changes" class="panel" hidden><h2>JS 변경분</h2><p class="muted">파일 내용 해시·분석기 버전 기준입니다. 캐시 재사용은 현재 서버 내용의 재확인을 의미하지 않습니다.</p><div id="changeRows"></div></section></main>
<script id="data" type="application/json">__DATA__</script><script>
'use strict'; const bundle=JSON.parse(document.getElementById('data').textContent),records=bundle.records,analysis=bundle.analysis,$=id=>document.getElementById(id),byId=new Map(records.map(r=>[r.observation_id,r]));
const searchIndex=new Map(records.map(r=>[r.observation_id,JSON.stringify([r.url,r.context,r.body.fields,r.body.text]).toLowerCase()]));
const stateNames={discovered:'발견',captured:'실제 요청 확보',queued:'검토 예정',testing:'검증 중',confirmed:'확인 (검토자)',false_positive:'오탐 (검토자)',deferred:'보류'};let selected=records[0]?.observation_id||'',tab='request',page=0,edited=new Set();
const text=(parent,tag,value)=>{const e=document.createElement(tag);e.textContent=value;parent.append(e);return e};function cells(parent,values){const tr=document.createElement('tr');for(const value of values)text(tr,'td',value);parent.append(tr);return tr}
function stats(){ $('stats').replaceChildren();for(const [label,value] of [['기록',records.length],['실제 요청',analysis.summary.observed],['검토 후보',analysis.summary.candidates],['미검토',records.filter(r=>!['confirmed','false_positive'].includes(r.review.state)).length],['응답 미수집',analysis.summary.missing_response],['body 미완전',analysis.summary.missing_body],['계정 라벨',analysis.summary.actor_labels]]){const e=text($('stats'),'div','');e.className='stat';text(e,'b',value);text(e,'span',label)}}
for(const [id,key] of [['actor','actor'],['method','method'],['source','source']])for(const value of [...new Set(records.map(r=>key==='actor'?r.context.actor:r[key]).filter(Boolean))].sort()){const o=text($(id),'option',value);o.value=value}
for(const [value,name] of Object.entries(stateNames)){for(const id of ['stateFilter','reviewState']){const o=text($(id),'option',name);o.value=value}}
function filtered(){const q=$('search').value.toLowerCase(),actor=$('actor').value,state=$('stateFilter').value,priority=$('priority').value,method=$('method').value,source=$('source').value,observed=$('observed').value;return records.filter(r=>(!actor||r.context.actor===actor)&&(!state||r.review.state===state)&&(!priority||r.triage.priority===priority)&&(!method||r.method===method)&&(!source||r.source===source)&&(!observed||String(r.observed)===observed)&&(!q||searchIndex.get(r.observation_id).includes(q)))}
function render(){const list=filtered();$('saveReview').disabled=!list.length;if(list.length&&!list.some(r=>r.observation_id===selected)){selected=list[0].observation_id;detail()}else if(!list.length){selected='';$('detailTitle').textContent='검색 결과 없음';for(const id of ['metadata','hints','missing','packet','bodyState'])$(id).textContent='';$('reviewNote').value=''}page=Math.min(page,Math.max(0,Math.ceil(list.length/100)-1));$('rows').replaceChildren();for(const r of list.slice(page*100,(page+1)*100)){const tr=cells($('rows'),[r.triage.priority+' / '+r.triage.score,r.method+' '+r.url,(r.context.actor||'미지정')+' / '+(r.context.scenario||'미지정'),stateNames[r.review.state]||r.review.state]);tr.dataset.id=r.observation_id;if(r.observation_id===selected)tr.className='selected';tr.children[0].className=r.triage.priority;tr.onclick=()=>{selected=r.observation_id;render();detail()}}$('visible').textContent=list.length+'개 검색 결과 / 전체 '+records.length+'개 · 100개씩 표시';$('pageNo').textContent=(page+1)+' / '+Math.max(1,Math.ceil(list.length/100));$('prev').disabled=page===0;$('next').disabled=(page+1)*100>=list.length}
function packet(r,response=false){const msg=response?r.response:r;if(!msg)return '응답 미수집';return (response?'HTTP '+msg.status:r.method+' '+r.url)+'\n'+msg.headers.map(h=>h.name+': '+h.value).join('\n')+'\n\n'+(msg.body.text||'['+(msg.body.reason||msg.body.kind)+']')}
function detail(){const r=byId.get(selected);if(!r)return;$('detailTitle').textContent=r.method+' '+r.url;$('metadata').textContent='계정: '+(r.context.actor||'미지정')+' · 조직: '+(r.context.tenant||'미지정')+' · 출처: '+r.source+' · '+(r.observed?'실제 요청':'정적 발견')+' · 관찰 횟수: '+(r.seen_count||1);$('hints').replaceChildren();for(const h of r.triage.hints){text($('hints'),'p',h.reason+' → '+h.next_check)}$('missing').textContent='부족한 정보: '+(r.triage.missing.join(' · ')||'현재 수집 기준에서 없음');$('packet').textContent=tab==='json'?JSON.stringify(r,null,2):packet(r,tab==='response');$('bodyState').textContent=JSON.stringify({request:r.body,response:r.response?.body||null},null,2);$('reviewState').value=r.review.state;$('reviewNote').value=r.review.note||'';$('reviewMessage').textContent=''}
for(const id of ['actor','stateFilter','priority','method','source','observed'])$(id).onchange=()=>{page=0;render()};let debounce;$('search').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{page=0;render()},180)};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));detail()};
$('saveReview').onclick=()=>{const r=byId.get(selected);if(!r)return;const state=$('reviewState').value,note=$('reviewNote').value;if(note.length>4000||(['confirmed','false_positive'].includes(state)&&!note.trim())){$('reviewMessage').textContent='결론에는 증거 메모가 필요하며, 메모는 4,000자 이하여야 합니다.';return}r.review={state,note};edited.add(selected);stats();render();coverage();$('reviewMessage').textContent='이 화면에 적용했습니다. DB 반영은 변경 JSON을 내보낸 후 가져오세요.'};
$('exportReviews').onclick=()=>{const reviews=[...edited].map(id=>({observation_id:id,...byId.get(id).review}));const blob=new Blob([JSON.stringify({schema_version:'8.2',reviews},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='review_edits.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
function compare(){const pair=analysis.comparisons[Number($('pairSelect').value)];$('diffRows').replaceChildren();if(!pair){$('pairMeta').textContent='같은 자원의 서로 다른 계정 관찰이 없습니다. actor 라벨과 동일 URL·payload의 트래픽이 필요합니다.';return}const a=byId.get(pair.left_id),b=byId.get(pair.right_id);$('leftTitle').textContent=pair.left_actor+' / '+(pair.left_tenant||'조직 미지정');$('rightTitle').textContent=pair.right_actor+' / '+(pair.right_tenant||'조직 미지정');$('leftPacket').textContent=packet(a,true);$('rightPacket').textContent=packet(b,true);$('pairMeta').textContent='기대 권한: '+pair.left_expected+' / '+pair.right_expected+' · '+(pair.comparable?'본문 비교 가능':'본문 비교 불가: '+pair.reason)+' · 생략된 차이 '+pair.omitted_differences+' · 비교 표시 제한 '+analysis.comparison_truncated+' · '+pair.warning;for(const d of pair.differences)cells($('diffRows'),[d.field,d.left_missing?'[필드 없음]':JSON.stringify(d.left),d.right_missing?'[필드 없음]':JSON.stringify(d.right)])}
analysis.comparisons.forEach((p,i)=>{const o=text($('pairSelect'),'option',p.method+' '+p.url+' · '+p.left_actor+' ↔ '+p.right_actor);o.value=i});$('pairSelect').onchange=compare;
function coverage(){$('coverageRows').replaceChildren();for(const row of analysis.coverage){const states={};for(const id of row.observation_ids){const state=byId.get(id).review.state;states[state]=(states[state]||0)+1}cells($('coverageRows'),[row.method+' '+row.route,row.records+'건 / 실제 '+row.observed+'건',row.actors.join(', ')||'미지정',Object.entries(states).map(([k,v])=>(stateNames[k]||k)+': '+v).join(', '),row.missing.join(' · ')||'현재 수집 기준에서 없음'])}}
for(const flow of analysis.flows){const art=text($('flowRows'),'article','');text(art,'h3',flow.scenario+' · '+(flow.actor||'계정 미지정')+' / '+flow.tenant);text(art,'p','capture: '+flow.capture_id+' · 추가 생략 '+flow.truncated_steps);for(const step of flow.steps)text(art,'p',step.timestamp+' · '+step.method+' '+step.url);text(art,'pre',JSON.stringify(flow.links,null,2));text(art,'p',flow.warning)}if(!analysis.flows.length)text($('flowRows'),'p','scenario와 capture_id 라벨을 붙여 실제 트래픽을 가져오세요.');
const assets=new Map();for(const r of records)if(r.asset)assets.set((r.origin_url||'')+'|'+r.asset.content_hash+'|'+r.asset.analyzer_version,{url:r.origin_url,asset:r.asset});for(const {url,asset} of assets.values()){const art=text($('changeRows'),'article','');text(art,'h3',url||'JS 출처');text(art,'pre',JSON.stringify(asset,null,2))}if(!assets.size)text($('changeRows'),'p','내용 해시와 분석기 버전이 있는 JS 분석 기록이 없습니다.');
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{document.querySelectorAll('.panel').forEach(x=>x.hidden=x.id!==b.dataset.view);document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b))};stats();render();detail();compare();coverage();
</script></html>'''
